('PT158-S3-Q18','note','c32535cb-b319-4338-a6e2-e62341ec572c','C','f0948b2b-235f-4636-89fa-967e5a12bcd5','0d2771aa2be85e418f5cb2425fde216f','7fc1efe7b52600eabf543599bdfbcdbb',NULL,NULL),
('PT158-S3-Q18','note','c32535cb-b319-4338-a6e2-e62341ec572c','D','7745c34e-bc87-45bb-ad27-c20d86e952be','8a175294337547f9163c5b9c38edae83','e481e43a10b6178045a4032d096a311c',NULL,NULL),
('PT158-S3-Q18','note','c32535cb-b319-4338-a6e2-e62341ec572c','E','9625d1bf-cd58-4e5a-b56d-3612b62f0c42','4ddd6a18a42a03711324b754094a2cb7','cfa12194c7ab1401a82d5852a8c0547a',NULL,NULL)), actual as (
 select 'step'::text kind, explanation_id::text eid, position::text slot,id::text rid,md5(body) body_md5,coalesce(label,'') label from lr_explanation_steps
 union all select 'note',explanation_id::text,letter::text,id::text,md5(body),null::text from lr_explanation_choice_notes
), checked as (
 select e.*,count(a.rid)::integer matches,
 count(a.rid) filter(where a.body_md5=e.new_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.new_label))::integer final_matches,
 count(a.rid) filter(where a.body_md5=e.old_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.old_label))::integer old_matches,
 jsonb_agg(jsonb_build_object('rid',a.rid,'md5',a.body_md5,'label',a.label)) filter(where a.rid is not null) actual
 from expected e left join actual a on a.kind=e.kind and a.eid=e.eid and a.slot=e.slot
 group by e.qid,e.kind,e.eid,e.slot,e.rid,e.new_md5,e.old_md5,e.new_label,e.old_label
), extras as (
 select a.kind,a.eid,a.slot,count(*) count from actual a
 where a.eid in (select distinct eid from expected) and not exists(select 1 from expected e where e.eid=a.eid and e.kind=a.kind and e.slot=a.slot)
 group by a.kind,a.eid,a.slot
)
select jsonb_build_object('batch','e18','expected_rows',(select count(*) from checked),'final_rows',(select count(*) from checked where matches=1 and final_matches=1),'old_rows',(select count(*) from checked where matches=1 and old_matches=1),'missing',(select count(*) from checked where matches=0),'duplicate_slots',(select count(*) from checked where matches>1),'mismatches',coalesce((select jsonb_agg(jsonb_build_object('qid',qid,'kind',kind,'slot',slot,'expected_id',rid,'expected_md5',new_md5,'matches',matches,'old_matches',old_matches,'actual',actual)) from checked where matches<>1 or final_matches<>1),'[]'::jsonb),'extra_slots',coalesce((select jsonb_agg(to_jsonb(extras)) from extras),'[]'::jsonb)) audit;
